ruleContent.content:
@js:
var html = String(result || '');
var cid = '';
var m1 = html.match(/data-chapter-id="(\d+)"/);
if (m1) cid = m1[1];
if (!cid) {
  var m2 = html.match(/id:\s*'(\d+)'/);
  if (m2) cid = m2[1];
}
var content = '';
if (cid) {
  var om = baseUrl.match(/^https?:\/\/[^\/]+/);
  var origin = om ? om[0] : source.key;
  var apiUrl = origin + '/wmcms/ajax/index.php?action=novel.getchapter&cid=' + cid + '&format=1';
  var res = java.ajax(apiUrl);
  try {
    var json = JSON.parse(res);
    if (json.code == 200 && json.data && json.data.chapter) {
      var ch = json.data.chapter;
      if (String(ch.chapter_isvip) == '0' && ch.content && ch.content.length > 0) {
        var lines = [];
        for (var i = 0; i < ch.content.length; i++) lines.push(String(ch.content[i]));
        content = lines.join('\n');
      } else if (String(ch.chapter_isvip) != '0') {
        content = '【VIP章节，需订阅后阅读】';
      } else {
        content = '【本章内容为空】';
      }
    } else {
      content = '【接口返回异常 code=' + json.code + '】';
    }
  } catch(e) {
    content = '【JSON解析失败: ' + e + '】';
  }
} else {
  content = '【未能提取章节ID】';
}
result = content;
result;

